import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.util.StringTokenizer;

public class B {
    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintStream outStream = System.out;
        try {
            String line = reader.readLine();
            StringTokenizer tokenizer = new StringTokenizer(line);
            long R = Long.parseLong(tokenizer.nextToken());
            long C = Long.parseLong(tokenizer.nextToken());
            long answer = compute(R, C);
            outStream.println(answer);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static long compute(long r, long c) {
        if (r < 3 && c < 3) return 0;
        if (r == 1) {
            long total = c;
            long m = c % 6;
            if (m != 0) {
                if (m <= 3) total -= m;
                else if (m == 4) total -= 2;
                else total -= 1;
            }
            return total;
        }
        if (r == 2) {
            if (c == 3 || c == 7) return r * (c - 1);
            return r * c;
        }
        long totalCells = r * c;
        if (totalCells % 2 == 0) return totalCells;
        return totalCells - 1;
    }
}
